// GLOBAL VARIABLES (No imports needed!)

// 1. console (Prints to stdout/stderr)
console.log("I am globally available!");

// 2. Timers
// setTimeout(() => console.log("Timer finished"), 1000);

// 3. Current Directory and File (In CommonJS)
// Note: These don't work in standard ES Modules unless specifically enabled
console.log("Current Directory:", __dirname);
console.log("Current File:", __filename);

// 4. The 'process' object (Information about the running app)
console.log("Node Version:", process.version);
console.log("Platform:", process.platform);

// 5. The actual root global object (equivalent to 'window' in browsers)
// You can attach things to it (but it's considered bad practice)
global.myCustomAppSecret = "12345";
console.log(global.myCustomAppSecret);
